/**
 * Drizzle schema for every goodnight-web table. drizzle-kit generates the SQL
 * migrations in `migrations/` from this file (`bun run db:generate`); never
 * edit a migration that has been released (docs/decisions/0005).
 *
 * The Better Auth tables (`user`, `session`, `account`, `verification`,
 * `passkey`) and their relations are generated by the Better Auth CLI with
 * `scripts/auth-schema.config.ts`. Regenerate them after a Better Auth
 * upgrade instead of editing them by hand.
 */
import { relations, sql } from 'drizzle-orm';
import {
  check,
  index,
  integer,
  sqliteTable,
  text,
} from 'drizzle-orm/sqlite-core';
import type { FormDefinition } from '../features/contact-form/form-definition.ts';
import { SUBMISSION_STATUSES } from '../features/submissions/submission-status.ts';

/**
 * Contact form submissions. Times are unix milliseconds. `ip_hash` holds
 * `HMAC-SHA256(ip, IP_HASH_SECRET)`; the raw IP is never stored. The values
 * of the editable form fields are in `fields`, keyed by field id.
 */
export const submissions = sqliteTable(
  'submissions',
  {
    /** ULID, sortable by time. */
    id: text('id').primaryKey(),
    createdAt: integer('created_at').notNull(),
    /** The visitor's address. Fixed: it is not part of the editable form. */
    email: text('email').notNull(),
    status: text('status', { enum: SUBMISSION_STATUSES })
      .notNull()
      .default('unread'),
    /**
     * Set when the honeypot was filled or the spam score reached
     * `SPAM_SUSPECT_THRESHOLD`. Admins can clear or set it. Flagged rows are
     * never sent to Slack and are listed apart from the others.
     */
    suspectedSpam: integer('suspected_spam', { mode: 'boolean' })
      .notNull()
      .default(false),
    spamScore: integer('spam_score').notNull().default(0),
    /** JSON array of spam rule names. */
    spamReasons: text('spam_reasons'),
    ipHash: text('ip_hash'),
    userAgent: text('user_agent'),
    /** `request.cf.country`. */
    country: text('country'),
    /** Page that sent the form. */
    pagePath: text('page_path'),
    /** Privacy policy consent time; 0 when consent was not given. */
    consentAt: integer('consent_at').notNull(),
    /** Time of a delivered Slack notification. */
    notifiedAt: integer('notified_at'),
    readAt: integer('read_at'),
    /** Language of the page that sent the form (`ja` or `en`). */
    locale: text('locale'),
    /**
     * Values of the form fields as a JSON object, keyed by field id. Empty
     * fields are left out. Read it with the definition of `form_version`.
     */
    fields: text('fields', { mode: 'json' })
      .$type<unknown>()
      .notNull()
      .default(sql`'{}'`),
    /** The `form_definitions.version` the submission was validated against. */
    formVersion: integer('form_version').notNull().default(1),
  },
  (table) => [
    // Retention pruning and the admin list.
    index('idx_submissions_created').on(table.createdAt),
    // Admin list filtered by form version.
    index('idx_submissions_version_created').on(
      table.formVersion,
      table.createdAt,
    ),
    // Unread count and the unread and read views.
    index('idx_submissions_status_created').on(table.status, table.createdAt),
    // Keep in step with SUBMISSION_STATUSES (checked by a test).
    check(
      'submissions_status_check',
      sql`${table.status} in ('unread', 'read')`,
    ),
  ],
);

/**
 * Versions of the contact form definition. Rows are append-only: triggers in
 * migrations/0004 refuse UPDATE and DELETE, so a version never changes after
 * it is saved and old submissions always render with their own labels. The
 * highest version is the current form.
 */
export const formDefinitions = sqliteTable('form_definitions', {
  version: integer('version').primaryKey(),
  /** The {@link FormDefinition} as JSON. */
  definition: text('definition', { mode: 'json' })
    .$type<FormDefinition>()
    .notNull(),
  createdAt: integer('created_at').notNull(),
  /** Email of the admin who saved it; `null` for the built-in first version. */
  createdBy: text('created_by'),
  /** The version this one restored, when it was made by a restore. */
  restoredFrom: integer('restored_from'),
});

/**
 * Site settings as key-value text. Keys in use: `retention_days`,
 * `last_cleanup_at` (unix ms), and `setup_closed_at` (unix ms, claimed by the
 * first passkey registration and also written by the `passkey_closes_setup`
 * trigger in migrations/0002).
 */
export const settings = sqliteTable('settings', {
  key: text('key').primaryKey(),
  value: text('value').notNull(),
});

/** Better Auth users. Admins only; there is no public sign-up. */
export const user = sqliteTable('user', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  email: text('email').notNull().unique(),
  emailVerified: integer('email_verified', { mode: 'boolean' })
    .default(false)
    .notNull(),
  image: text('image'),
  createdAt: integer('created_at', { mode: 'timestamp_ms' })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
    .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
    .$onUpdate(() => new Date())
    .notNull(),
});

/** Better Auth sessions. `ip_address` stays empty (IP tracking is off). */
export const session = sqliteTable(
  'session',
  {
    id: text('id').primaryKey(),
    expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
    token: text('token').notNull().unique(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text('ip_address'),
    userAgent: text('user_agent'),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
  },
  (table) => [index('session_userId_idx').on(table.userId)],
);

/** Better Auth accounts. Unused columns stay empty (no passwords, no OAuth). */
export const account = sqliteTable(
  'account',
  {
    id: text('id').primaryKey(),
    accountId: text('account_id').notNull(),
    providerId: text('provider_id').notNull(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    accessToken: text('access_token'),
    refreshToken: text('refresh_token'),
    idToken: text('id_token'),
    accessTokenExpiresAt: integer('access_token_expires_at', {
      mode: 'timestamp_ms',
    }),
    refreshTokenExpiresAt: integer('refresh_token_expires_at', {
      mode: 'timestamp_ms',
    }),
    scope: text('scope'),
    password: text('password'),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index('account_userId_idx').on(table.userId)],
);

/** Better Auth verification values, such as passkey challenges. */
export const verification = sqliteTable(
  'verification',
  {
    id: text('id').primaryKey(),
    identifier: text('identifier').notNull(),
    value: text('value').notNull(),
    expiresAt: integer('expires_at', { mode: 'timestamp_ms' }).notNull(),
    createdAt: integer('created_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .notNull(),
    updatedAt: integer('updated_at', { mode: 'timestamp_ms' })
      .default(sql`(cast(unixepoch('subsecond') * 1000 as integer))`)
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index('verification_identifier_idx').on(table.identifier)],
);

/** Passkeys registered by admins (Better Auth passkey plugin). */
export const passkey = sqliteTable(
  'passkey',
  {
    id: text('id').primaryKey(),
    name: text('name'),
    publicKey: text('public_key').notNull(),
    userId: text('user_id')
      .notNull()
      .references(() => user.id, { onDelete: 'cascade' }),
    credentialID: text('credential_id').notNull(),
    counter: integer('counter').notNull(),
    deviceType: text('device_type').notNull(),
    backedUp: integer('backed_up', { mode: 'boolean' }).notNull(),
    transports: text('transports'),
    createdAt: integer('created_at', { mode: 'timestamp_ms' }),
    aaguid: text('aaguid'),
  },
  (table) => [
    index('passkey_userId_idx').on(table.userId),
    index('passkey_credentialID_idx').on(table.credentialID),
  ],
);

/** Relations of {@link user}. */
export const userRelations = relations(user, ({ many }) => ({
  sessions: many(session),
  accounts: many(account),
  passkeys: many(passkey),
}));

/** Relations of {@link session}. */
export const sessionRelations = relations(session, ({ one }) => ({
  user: one(user, {
    fields: [session.userId],
    references: [user.id],
  }),
}));

/** Relations of {@link account}. */
export const accountRelations = relations(account, ({ one }) => ({
  user: one(user, {
    fields: [account.userId],
    references: [user.id],
  }),
}));

/** Relations of {@link passkey}. */
export const passkeyRelations = relations(passkey, ({ one }) => ({
  user: one(user, {
    fields: [passkey.userId],
    references: [user.id],
  }),
}));
